// Парсинг ответа Google AI Studio
const input = $input.first().json;
const prevData = $('Парсинг сообщения').first().json;

let analysis = {};
try {
  let text = '';
  if (input.candidates && input.candidates[0]) {
    text = input.candidates[0].content.parts[0].text;
  }
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analysis = JSON.parse(text);
} catch (e) {
  analysis = {
    task_type: 'другое', task_subtype: 'не определён', complexity: 5,
    required_skills: ['требуется ручной анализ'],
    budget_assessment: 'требует оценки', budget_fair_range: 'N/A',
    red_flags: ['AI не смог распарсить'], green_flags: [],
    recommendation: 'обсудить_условия',
    recommendation_reason: 'Требуется ручной анализ',
    estimated_hours: 0, can_automate: false, automation_approach: null
  };
}

return [{ json: { ...prevData, analysis } }];
